sys_script_include.script:
var HSBCWORMUtils = Class.create();
HSBCWORMUtils.prototype = {
    initialize: function() {},
    //targetDate formate: YYYYMMDD
    generateCSVAndSave: function(tableName, query, targetDate) {
        try {
            //gs.info('HSBCWORMUtils.generateCSVAndSave query: ' + tableName + '-' + query);
            // Validate inputs
            if (!tableName || !query) {
                throw new Error("Table name and query are required.");
            }

            // Query the table
            var tablerecord = new GlideRecord(tableName);
            tablerecord.initialize(); // initialize
            var fields = tablerecord.getElements(); // Get field elements

            try {
                tablerecord.addEncodedQuery(query);
                tablerecord.query();
            } catch (error) {
                gs.error("Error in generateCSVAndSave query: " + error.message);
            }

            // Prepare CSV content
            var csvContent = [];
            var header = [];
            var fieldNames = [];

            if (tablerecord.next()) {
                fields.forEach((field) => {
                    var fieldName = field.getName(); // Get field name
                    fieldNames.push(fieldName);
                    var fieldLabel = field.getLabel(); // Get field label
                    header.push(fieldLabel);
                });
                csvContent.push(header.join(","));
            }

            var count = 0;
            // Add rows
            do {
                var row = [];
                fieldNames.forEach((fieldName) => {
                    var fieldValue = tablerecord.getValue(fieldName);
                    row.push(this.convertForCSV(fieldValue));
                });
                csvContent.push(row.join(","));
                count++;
            } while (tablerecord.next());

            // Generate CSV string
            if (csvContent !== null && csvContent.length > 1) {

                var csvString = csvContent.join("\n");
                //gs.info('HSBCWORMUtils - csvString: ' + csvString);

                // Generate file name
                var fileName = tableName + "_" + targetDate + ".csv";

                // Save to sys_attachment
                var attachment = new GlideSysAttachment();
                var attachmentSysId = attachment.write(tablerecord,
                    fileName,
                    "text/csv",
                    csvString
                );

                // Return sys_id and count of the attachment
                return attachmentSysId + '-' + count + '-' + fileName;

            }
        } catch (error) {
            gs.error("Error in generateCSVAndSave: " + error.message);
            return null;
        }
    },

    generateCSVWithoutCTAC: function(tableName, query, targetDate, excludeFields) {
        try {
            //gs.info('HSBCWORMUtils.generateCSVAndSave query: ' + tableName + '-' + query);
            // Validate inputs
            if (!tableName || !query) {
                throw new Error("Table name and query are required.");
            }

            // Query the table
            var tablerecord = new GlideRecord(tableName);
            tablerecord.initialize(); // initialize
            var fields = tablerecord.getElements(); // Get field elements

            try {
                tablerecord.addEncodedQuery(query);
                tablerecord.query();
            } catch (error) {
                gs.error("Error in generateCSVWithoutCTAC query: " + error.message);
            }

            // Prepare CSV content
            var csvContent = [];
            var header = [];
            var fieldNames = [];

            if (tablerecord.next()) {
                fields.forEach((field) => {
                    var fieldName = field.getName(); // Get field name
                    var fieldLabel = field.getLabel(); // Get field label
                    // Filter out excluded fields
                    if (excludeFields.indexOf(fieldLabel) === -1) {
                        fieldNames.push(fieldName);
                        header.push(fieldLabel);
                    }
                });
                csvContent.push(header.join(","));
            }

            var count = 0;
            // Add rows
            do {
                var row = [];
                fieldNames.forEach((fieldName) => {
                    var fieldValue = tablerecord.getValue(fieldName);
                    row.push(this.convertForCSV(fieldValue));
                });
                csvContent.push(row.join(","));
                count++;
            } while (tablerecord.next());

            // Generate CSV string
            if (csvContent !== null && csvContent.length > 1) {

                var csvString = csvContent.join("\n");
                //gs.info('HSBCWORMUtils - csvString: ' + csvString);

                // Generate file name
                var fileName = tableName + "_" + targetDate + ".csv";

                // Save to sys_attachment
                var attachment = new GlideSysAttachment();
                var attachmentSysId = attachment.write(tablerecord,
                    fileName,
                    "text/csv",
                    csvString
                );
                //gs.info('HSBCWORMUtils - count: ' + count);
                // Return sys_id and count of the attachment
                return attachmentSysId + '-' + count + '-' + fileName;

            }
        } catch (error) {
            gs.error("Error in generateCSVWithoutCTAC: " + error.message);
            return null;
        }

    },
    calculateMD5: function(attachmentSysId) {
        try {
            var attachment = new GlideRecord('sys_attachment');
            if (attachment.get(attachmentSysId)) {

                //read file content
                var inputStream = new GlideSysAttachment().getContentStream(attachmentSysId);
                if (!inputStream) {
                    return "Error: Unable to read content stream for sys_id: " + attachmentSysId;
                }

                //calculate MD5 checksum
                var digest = new GlideDigest();
                var md5Hex = digest.getMD5HexFromInputStream(inputStream);
                // Log the MD5 checksum for debugging
                gs.info("MD5 checksum for sys_id " + attachmentSysId + ": " + md5Hex);

                // Return MD5 checksum
                return md5Hex.toLowerCase();
            } else {
                return "Attachment not found for sys_id: " + attachmentSysId;
            }
        } catch (e) {
            return "Error calculating MD5: " + e.message;
        }
    },

    //targetDate formate: YYYYMMDD
    generatevalCSV: function(val_csv_content, targetDate) {
        try {
            // Generate validation file name
            var val_fileName = 'iqubetousworm_CE_HSI_Checksum_' + targetDate + '.csv';
            var rec = new GlideRecord('sys_attachment');

            // Save to sys_attachment
            var val_attachment = new GlideSysAttachment();
            var val_attachmentSysId = val_attachment.write(rec,
                val_fileName,
                "text/csv",
                val_csv_content
            );

            // Return sys_id of the attachment
            return val_attachmentSysId;
        } catch (error) {
            gs.error("Error in generatevalCSV: " + error.message);
            return null;
        }
    },

    UpdateFileId: function(fileProperty, fileId) {
        //var propertyName = "x_hsb11_hsbc_mss_t.worm_ce_hsi_data_file_list";

        var propertyName = fileProperty;

        var currentValue = gs.getProperty(propertyName);
        gs.info("Current datafiles: " + currentValue);

        var property = new GlideRecord('sys_properties');
        if (property.get('name', propertyName)) {
            property.value = fileId;
            property.update();
            gs.info("Property " + propertyName + " updated to: " + fileId);
        } else {
            gs.info("Property " + propertyName + " not found.");
        }
    },
    //check inputDate format - 'YYYYMMDD'
    isValidDate: function(dateString) {
        if (dateString.length !== 8 || isNaN(dateString)) {
            return false;
        }

        var year = parseInt(dateString.substring(0, 4), 10);
        var month = parseInt(dateString.substring(4, 6), 10) - 1; // start from 0 for month
        var day = parseInt(dateString.substring(6, 8), 10);

        var date = new Date(year, month, day);

        // check date
        return (
            date.getFullYear() === year &&
            date.getMonth() === month &&
            date.getDate() === day
        );
    },

    //format date for query date as 'YYYY-MM-DD'
    formatDate: function(dateString) {
        if (dateString.length !== 8 || isNaN(dateString)) {
            return "Invalid date format";
        }
        const year = dateString.substring(0, 4);
        const month = dateString.substring(4, 6);
        const day = dateString.substring(6, 8);


        return `${year}-${month}-${day}`;
    },

    //get trades by entity
    getTradeIdsByEntity: function(date_query) {

        var trade_records = [];
        var trade_query = date_query + 'u_entity=HSI';
        gs.info('HSBCWORMUtils - trade_query = ' + trade_query);

        try {
            var trade_gr = new GlideRecord('x_hsb11_hsbc_mss_t_hsbc_trade');
            trade_gr.addEncodedQuery(trade_query);
            trade_gr.query();

            while (trade_gr.next()) {
                trade_records.push(trade_gr.getValue('u_id'));
            }

        } catch (error) {
            gs.error("Error in getTradeIdsByEntity: " + error.message);
        }

        return trade_records;
    },

    //get trades by entity & trade_staus in case table
    getTradeIdsByStatus: function(date_query /*, status*/ ) {

        var trade_records = [];
        //var status_query = status.map(item => `trade_status=${item}`).join('^OR');
        var case_query = date_query + 'entityLIKEHSI' /*+ '^' + status_query*/ ;
        gs.info('HSBCWORMUtils - case_query = ' + case_query);

        try {
            var case_gr = new GlideRecord('x_hsb11_hsbc_mss_t_trade_case');
            case_gr.addEncodedQuery(case_query);
            case_gr.query();

            while (case_gr.next()) {
                var tradeSysId = case_gr.getValue('financial_object');
                if (tradeSysId) {
                    var trade_gr = new GlideRecord('x_hsb11_hsbc_mss_t_hsbc_trade');
                    if (trade_gr.get(tradeSysId)) {
                        var tradeId = trade_gr.getValue('u_id');
                        trade_records.push(tradeId);
                        //gs.info('HSBCWORMUtils - financial_object.u_id = ' + tradeId);
                    } else {
                        gs.info('No trade record found for sys_id: ' + tradeSysId);
                    }

                }
            }

        } catch (error) {
            gs.error("Error in getTradeIdsByStatus: " + error.message);
        }

        return trade_records;
    },

    //get Trade Ternimal Status
    getTermimalStatus: function(query) {

        var status = [];
        query = 'terminal_stage=true^business_process=c0ccc3d21b079950ff37eb14b24bcb9f';
        gs.info('HSBCWORMUtils - query = ' + query);

        try {
            var bps_gr = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage');
            bps_gr.addEncodedQuery(query);
            bps_gr.query();

            while (bps_gr.next()) {
                status.push(bps_gr.getValue('status'));
            }

        } catch (error) {
            gs.error("Error in getTermimalStatus: " + error.message);
        }

        return status;
    },

    //get HSI records in 'x_hsb11_hsbc_mss_o_mss_event_inbound'
    RetrieveEventInboundData: function(tradeIds, targetDate, excludeFields) {

        if (!Array.isArray(tradeIds) || tradeIds.length === 0) {
            gs.error("Invalid tradeIds array");
            return '';
        } else {
            try {
                var event_gr = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_inbound');
                event_gr.addQuery('objectid', 'IN', tradeIds);
                event_gr.query();

                // Prepare CSV content
                var csvContent = [];
                var headers = [];
                var count = 0;
                while (event_gr.next()) {
                    count++;
                    var row = [];
                    var fields = event_gr.getElements();
                    fields.forEach((field) => {
                        var fieldName = field.getName(); // Get field name
                        var fieldLabel = field.getLabel(); // Get field label
                        var fieldValue = field.getValue(fieldName);
                        // Filter out excluded fields
                        if (excludeFields.indexOf(fieldLabel) === -1) {
                            if (headers.indexOf(fieldLabel) === -1) {
                                headers.push(fieldLabel);
                            }
                            row.push(this.convertForCSV(fieldValue));
                        }

                    });
                    csvContent += row.join(',') + '\n';
                }
                csvContent = headers.join(',') + '\n' + csvContent;
                //gs.info('RetrieveEventInboundData - csvContent: ' + csvContent);

            } catch (error) {
                gs.error("Error in RetrieveEventInboundData: " + error.message);
            }
            // Generate CSV string
            if (count >= 1) {

                // Generate file name
                var fileName = 'x_hsb11_hsbc_mss_o_mss_event_inbound' + "_" + targetDate + ".csv";

                // Save to sys_attachment
                var attachment = new GlideSysAttachment();
                var attachmentSysId = attachment.write(event_gr,
                    fileName,
                    "text/csv",
                    csvContent
                );
                // Return sys_id and count of the attachment
                return attachmentSysId + '-' + count + '-' + fileName;
            }
        }
    },

    //handle the data in CSV file
    convertForCSV: function(value) {
        if (value == null || value === '') {
            return '""';
        }

        value = value.toString();

        if (value.includes(',') || value.includes('\n') || value.includes('"')) {
            value = value.replace(/"/g, '""');
            return `"${value}"`;
        }

        return value;
    },

    //get HSI records in 'x_hsb11_hsbc_mss_o_mss_email_inbound'
    RetrieveEmailInboundData: function(tradeIds, targetDate) {
        if (!Array.isArray(tradeIds) || tradeIds.length === 0) {
            gs.error("Invalid tradeIds array");
            return '';
        } else {
            var encodedQuery = '';
            for (var i = 0; i < tradeIds.length; i++) {
                if (i > 0) {
                    encodedQuery += '^OR';
                }
                encodedQuery += 'payloadLIKE' + tradeIds[i];
            }

            gs.info('HSBCWORMUtils - RetrieveEmailInboundData encodedQuery = ' + encodedQuery);

            try {
                var email_gr = new GlideRecord('x_hsb11_hsbc_mss_o_mss_email_inbound');
                email_gr.addEncodedQuery(encodedQuery);
                email_gr.query();

                // Prepare CSV content
                var csvContent = [];
                var headers = [];
                var count = 0;
                while (email_gr.next()) {
                    count++;
                    var row = [];
                    var fields = email_gr.getElements();
                    fields.forEach((field) => {
                        var fieldName = field.getName(); // Get field name
                        var fieldLabel = field.getLabel(); // Get field label
                        var fieldValue = field.getValue(fieldName);
                        if (headers.indexOf(fieldLabel) === -1) {
                            headers.push(fieldLabel);
                        }
                        row.push(this.convertForCSV(fieldValue));
                    });
                    csvContent += row.join(',') + '\n';
                }
                csvContent = headers.join(',') + '\n' + csvContent;
                //gs.info('RetrieveEmailInboundData - csvContent: ' + csvContent);

            } catch (error) {
                gs.error("Error in RetrieveEmailInboundData: " + error.message);
            }
            // Generate CSV string
            if (count >= 1) {

                // Generate file name
                var fileName = 'x_hsb11_hsbc_mss_o_mss_email_inbound' + "_" + targetDate + ".csv";

                // Save to sys_attachment
                var attachment = new GlideSysAttachment();
                var attachmentSysId = attachment.write(email_gr,
                    fileName,
                    "text/csv",
                    csvContent
                );
                // Return sys_id and count of the attachment
                return attachmentSysId + '-' + count + '-' + fileName;
            }
        }
    },

    type: 'HSBCWORMUtils'

};
